import numpy as np

def unit(v):
    v = np.array(v, float); return v/np.linalg.norm(v)

t = np.radians(6.0)
Rcc = 1.42; Rring = Rcc/(2*np.sin(np.pi/5)); dTiCp = 2.05
d1 = np.array([-np.sin(t),0, np.cos(t)]); d2 = np.array([-np.sin(t),0,-np.cos(t)])
c1 = d1*dTiCp; c2 = d2*dTiCp
u1 = np.array([-np.cos(t),0,-np.sin(t)]); u2 = np.array([-np.cos(t),0, np.sin(t)])
v  = np.array([0,1,0])
ringC={1:[],2:[]}; ringMe={1:[],2:[]}
for i,(c,u) in enumerate([(c1,u1),(c2,u2)],1):
    for k in range(5):
        phi=np.radians(72*k); rad=np.cos(phi)*u+np.sin(phi)*v; C=c+Rring*rad
        ringC[i].append(C)
        if k!=0: ringMe[i].append(C+1.51*rad)
ipso1, ipso2 = ringC[1][0], ringC[2][0]
Si1 = ipso1+1.87*u1; Si2 = ipso2+1.87*u2
print("Si1",Si1,"Si2",Si2)

c109 = np.cos(np.radians(109.5))
best=None
for chi in np.linspace(0, 2*np.pi, 721):
    py, pz = 0.77*np.sin(chi), 0.77*np.cos(chi)
    # solve px: (px-Si1x)^2 + (py-Si1y)^2 + (pz-Si1z)^2 = 1.87^2
    rem = 1.87**2 - (py-Si1[1])**2 - (pz-Si1[2])**2
    if rem < 0: continue
    for sgn in (-1,):
        px = Si1[0] + sgn*np.sqrt(rem)
        Ca = np.array([px,py,pz]); Cb = np.array([px,-py,-pz])
        aSi = np.degrees(np.arccos(np.clip(np.dot(unit(ipso1-Si1),unit(Ca-Si1)),-1,1)))
        aC  = np.degrees(np.arccos(np.clip(np.dot(unit(Si1-Ca),unit(Cb-Ca)),-1,1)))
        score = (aSi-109.5)**2 + (aC-109.5)**2
        if best is None or score < best[0]:
            best = (score, chi, px, py, pz, aSi, aC)
score, chi, px, py, pz, aSi, aC = best
Ca = np.array([px,py,pz]); Cb = np.array([px,-py,-pz])
print("chi(deg)=%.1f Ca=%s aSi=%.1f aC=%.1f score=%.1f"%(np.degrees(chi),Ca,aSi,aC,score))
print("Si1-Ca",np.linalg.norm(Si1-Ca),"Ca-Cb",np.linalg.norm(Ca-Cb))

def two_more(d1v,d2v):
    d1v,d2v=unit(d1v),unit(d2v); m=unit(d1v+d2v); n=unit(np.cross(d1v,d2v))
    cb=np.dot(d1v,m); a=1.0/(3*cb); b=np.sqrt(max(1-a*a,1e-9))
    return unit(-a*m+b*n), unit(-a*m-b*n)
def three_more(d):
    d=unit(d)
    p=np.array([1,0,0]) if abs(d[0])<0.9 else np.array([0,1,0])
    p=unit(p-np.dot(p,d)*d); q=unit(np.cross(d,p)); out=[]
    for phi in (0,120,240):
        e=-d/3.0+(np.sqrt(8)/3)*(np.cos(np.radians(phi))*p+np.sin(np.radians(phi))*q)
        out.append(unit(e))
    return out

atoms=[('Ti',np.zeros(3))]
for i in (1,2):
    for C in ringC[i]: atoms.append(('C',C))
    for C in ringMe[i]: atoms.append(('C',C))
atoms += [('Si',Si1),('Si',Si2)]
e1,e2 = two_more(ipso1-Si1, Ca-Si1); SiMe1=[Si1+1.86*e1, Si1+1.86*e2]
e1,e2 = two_more(ipso2-Si2, Cb-Si2); SiMe2=[Si2+1.86*e1, Si2+1.86*e2]
for C in SiMe1+SiMe2: atoms.append(('C',C))
w = unit(-(d1+d2)); TiMe = w*2.10
atoms += [('C',Ca),('C',Cb),('C',TiMe)]
H=[]
for i in (1,2):
    for k in range(1,5):
        Me=ringMe[i][k-1]; parent=ringC[i][k]
        for e in three_more(parent-Me): H.append(Me+1.09*e)
for Me,parent in [(SiMe1[0],Si1),(SiMe1[1],Si1),(SiMe2[0],Si2),(SiMe2[1],Si2)]:
    for e in three_more(parent-Me): H.append(Me+1.09*e)
e1,e2 = two_more(Si1-Ca, Cb-Ca); H.append(Ca+1.09*e1); H.append(Ca+1.09*e2)
e1,e2 = two_more(Si2-Cb, Ca-Cb); H.append(Cb+1.09*e1); H.append(Cb+1.09*e2)
for e in three_more(-TiMe): H.append(TiMe+1.09*e)
for h in H: atoms.append(('H',h))

P=np.array([a[1] for a in atoms])
D=np.linalg.norm(P[:,None,:]-P[None,:,:],axis=-1); np.fill_diagonal(D,1e9)
print("min pair dist:",D.min())
with open('guess.xyz','w') as f:
    f.write(f"{len(atoms)}\ninitial guess ansa-Ti(III) methyl complex\n")
    for el,xyz in atoms: f.write(f"{el} {xyz[0]:.6f} {xyz[1]:.6f} {xyz[2]:.6f}\n")
print("atoms:",len(atoms))
